"""Outbound fetch helper shared by every ingest feed."""
import time

DEFAULT_TIMEOUT = 30
DEFAULT_RETRIES = 3


def fetch(url, session, timeout=DEFAULT_TIMEOUT, retries=DEFAULT_RETRIES):
    """GET url through session, retrying timeouts with exponential backoff."""
    attempt = 0
    while True:
        try:
            return session.get(url, timeout=timeout)
        except TimeoutError:
            attempt += 1
            if attempt > retries:
                raise
            time.sleep(2 ** attempt)

