"""Batching entry point for the ingest feeds."""
from . import config
from . import fetcher


def run(urls, session, sink):
    batch = []
    limit = int(config.get("ingest_batch_size"))
    for url in urls:
        batch.append(fetcher.fetch(url, session))
        if len(batch) >= limit:
            sink.write(batch)
            batch = []
    if batch:
        sink.write(batch)
    return len(urls)

